// Highlight the current page's nav link (project detail pages highlight "Projects")
(function () {
  const path = window.location.pathname;
  const page = path.split('/').pop() || 'index.html';
  const inProjects = /\/projects\/[^/]+$/.test(path);
  document.querySelectorAll('.nav-links a').forEach(a => {
    const target = a.getAttribute('href').split('/').pop();
    if (target === page || (inProjects && target === 'projects.html')) a.classList.add('active');
  });
})();

// Filter tabs: show/hide the pre-rendered entries (generated by build.py) by their data-tags
(function () {
  const buttons = document.querySelectorAll('.filter-btn');
  const grid = document.querySelector('.card-grid');
  if (!grid || !buttons.length) return;

  const entries = grid.querySelectorAll('.card-entry');
  const empty = grid.querySelector('.empty-state');

  buttons.forEach(btn => {
    btn.addEventListener('click', () => {
      buttons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const filter = btn.dataset.filter;
      let shown = 0;
      entries.forEach(el => {
        const match = filter === 'all' || el.dataset.tags.split(',').includes(filter);
        el.hidden = !match;
        if (match) shown++;
      });

      if (empty) {
        empty.textContent = `No ${empty.dataset.label} tagged "${filter}".`;
        empty.hidden = shown > 0;
      }
    });
  });
})();
